    return {...box,x:Math.round((Number(panel.x)||0)+(Number(def.x)||0)-(Number(panelBase.x)||0)),y:Math.round((Number(panel.y)||0)+(Number(def.y)||0)-(Number(panelBase.y)||0)),w:def.w,h:def.h,anchor:'top-left'};
