  guiStudioSpaceHandActive=false;
  guiStudioToolBeforeSpace=null;
  $('#guiStudioModal')?.classList.remove('gui-studio-space-hand');
  $$('.gui-studio-sketch-tools>button').forEach(tool=>tool.classList.remove('space-active'));
